def endpoint(base_url, path):
    # Strip a trailing /v1 or /v1/ already present in the base URL, preserving
    # any deployment prefix (e.g. .../proxy/v1 -> .../proxy).
    if base_url.endswith('/v1/'):
        base_url = base_url[:-4]
    elif base_url.endswith('/v1'):
        base_url = base_url[:-3]
    # Insert exactly one /v1 before the relative resource path.
    return base_url.rstrip('/') + '/v1/' + path.lstrip('/')

